    std::vector<double>sine(1024),twice(1024);for(std::size_t j=0;j<sine.size();++j)twice[j]=2*(sine[j]=std::sin(2*pi*.1*j));const auto power=run(PENTA_SCIENCE_WELCH,{{"segment",201},{"nfft",257},{"fs",100}},sine);const auto integral=std::accumulate(power.data.begin(),power.data.end(),0.)*100/257;check(std::abs(integral-.5)<.002,"Prime-length Welch PSD integrates to independent sine variance.");const auto cross=run(PENTA_SCIENCE_CROSS,{{"segment",201},{"nfft",257}},sine,{},twice);for(std::size_t j=0;j<cross.data.size()/5;++j)if(cross.data[5*j+3]>1e-6)check(std::abs(cross.data[5*j+2]-1)<1e-12,"Native coherence is one for an exactly scaled signal.");
    std::vector<double>impulse(8);impulse[0]=1;const auto filtered=run(PENTA_SCIENCE_FILTER,Json::object(),impulse,{.5,.5},{1});check(filtered.data[0]==.5&&filtered.data[1]==.5&&filtered.data[2]==0,"DF2T filtering matches the analytic two-tap impulse response.");const auto butter=run(PENTA_SCIENCE_BUTTER,{{"order",4},{"cutoff",10},{"fs",100}});std::vector<double>b(butter.data.begin(),butter.data.begin()+5),a(butter.data.begin()+5,butter.data.end());check(std::abs(std::accumulate(b.begin(),b.end(),0.)/std::accumulate(a.begin(),a.end(),0.)-1)<1e-12,"Butterworth lowpass has independent unit DC gain.");const auto constant=run(PENTA_SCIENCE_FILTFILT,Json::object(),std::vector<double>(100,2),b,a);for(auto x:constant.data)check(std::abs(x-2)<1e-12,"Forward/reverse steady initials preserve a constant signal.");
