    const auto largeMedian=run(PENTA_SCIENCE_BOOTSTRAP,{{"replicates",32},{"statistic","median"}},{1e308,1e308});check(std::all_of(largeMedian.data.begin(),largeMedian.data.end(),[](double x){return x==1e308;})&&largeMedian.meta.at("original")==1e308,"Even medians of equal large finite samples retain the common observation.");
    const auto largeRms=run(PENTA_SCIENCE_BOOTSTRAP,{{"replicates",32},{"statistic","rms"}},{1e200,1e200});check(std::all_of(largeRms.data.begin(),largeRms.data.end(),[](double x){return x==1e200;}),"RMS takes the wide square root before narrowing a representable result.");
